    <div class="max-w-[1400px] mx-auto w-full grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-20 items-center">
      
      <div>
        <div class="relative inline-block mb-6">
          <h2 class="text-4xl md:text-5xl font-bold text-[#0b355b] relative z-10">
            About Us
          </h2>
          <div class="absolute -top-12 -left-20 w-full h-full opacity-60" >
            <svg class="w-[400px]" viewBox="0 0 800 400"><path d="M112.10762023925781,257.39910888671875C149.56053436279296,233.73094757080077,176.23317581176758,181.24664596557616,241.25559997558594,175.78475952148438C306.2780241394043,170.3228730773926,252.8340769958496,245.06725967407226,336.3228759765625,238.5650177001953C419.8116749572754,232.06277572631836,434.99553833007815,149.2018000793457,529.1480102539062,153.3632354736328C623.3004821777344,157.52467086791992,622.7533892822265,224.04484268188477,660.986572265625,252.914794921875" fill="none" stroke-width="23" stroke="hsl(50, 90%, 38%)" stroke-linecap="round" transform="matrix(0.7314210254961915,-2.7755575615628914e-16,-2.7755575615628914e-16,-0.7314210254961915,117.27132087616468,350.2017651289411)" stroke-dasharray="97 48" stroke-opacity="1"></path><defs><linearGradient id="SvgjsLinearGradient1000"><stop stop-color="hsl(37, 99%, 67%)" offset="0"></stop><stop stop-color="hsl(316, 73%, 52%)" offset="1"></stop></linearGradient></defs></svg>
          </div>
        </div>
        
        <p class="text-gray-600 text-sm md:text-base leading-relaxed">
          Images, Videos, PDFs and audio files are supported. Create multi impressions and dynamic directs from the app. Take photos with the mobile app and save them in a note.
        </p>
      </div>

      <div class="w-full aspect-video bg-[#cde0fb] rounded-sm shadow-md">
            <img src="src/assets/bglogin.jpg" alt="Background Login" class="w-full h-full object-cover rounded-sm"/>
      </div>

    </div>
  </section>
  <section id="gallery" class="relative w-full min-h-[80vh] bg-gradient-to-r from-[#0b355b] to-[#1a5c8c] px-6 pt-24 pb-20 scroll-mt-24 flex ">
        <div class="absolute overflow-hidden top-0 right-0 w-full h-full flex items-center justify-center z-0 opacity-30 pointer-events-none">
          <img src="src/assets/bg-bawah.svg" alt="Background Waves" class="min-w-[1000px] w-full h-full object-cover" />        
        </div>
    <div class="max-w-[1400px] mx-auto w-full flex flex-col items-center">
      
      <div class="text-center mb-16">
        <div class="relative inline-block">
          <h2 class="text-4xl md:text-5xl font-bold text-white relative z-10">Gallery</h2>
          <div class="absolute -top-10 -left-20 w-full h-full opacity-60" >
            <svg class="min-w-[350px]" viewBox="0 0 800 400"><path d="M133.63229370117188,273.5426025390625C178.1255682373047,270.64872772216796,283.36025446573893,260.2780115763346,354.2601013183594,259.19281005859375C425.1599481709798,258.1076085408529,458.79520991007485,266.3527646891276,485.2017822265625,268.16143798828125" fill="none" stroke-width="14" stroke="hsl(30, 100%, 40%)" stroke-linecap="round" transform="matrix(-1.0500000000000007,8.743006318923108e-16,-8.743006318923108e-16,-1.0500000000000007,724.8878898620611,479.6508918762206)" stroke-dasharray="56 28" stroke-opacity="1"></path><defs><linearGradient id="SvgjsLinearGradient1000"><stop stop-color="hsl(37, 99%, 67%)" offset="0"></stop><stop stop-color="hsl(316, 73%, 52%)" offset="1"></stop></linearGradient></defs></svg>          </div>
        </div>
        <p class="text-white text-sm mt-4">All Images</p>
      </div>

      <div class="relative w-full max-w-6xl flex items-center justify-center px-12 md:px-16">
        
        <button on:click={slideLeft} class="absolute left-0 z-20 w-10 h-10 bg-[#e2e8f0] hover:bg-white rounded-full flex items-center justify-center shadow-lg transition-colors group cursor-pointer">
          <svg class="w-6 h-6 text-gray-500 group-hover:text-gray-800" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/>
          </svg>
        </button>

        <div 
          bind:this={sliderContainer}
          class="w-full flex gap-8 overflow-x-auto snap-x snap-mandatory scroll-smooth hilangkan-scrollbar py-4"
        >
          {#each galleryItems as item}
            <div class="w-full md:w-[calc(50%-1rem)] shrink-0 snap-center aspect-[4/3] bg-[#cde0fb] rounded-sm shadow-xl flex items-center justify-center overflow-hidden">
              
              <span class="text-[#0b355b]/50 font-bold text-2xl">{item.title}</span>
              
            </div>
          {/each}
        </div>

        <button on:click={slideRight} class="absolute right-0 z-20 w-10 h-10 bg-[#e2e8f0] hover:bg-white rounded-full flex items-center justify-center shadow-lg transition-colors group cursor-pointer">
          <svg class="w-6 h-6 text-gray-500 group-hover:text-gray-800" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/>
          </svg>
        </button>

      </div>

    </div>
  </section>



</div>

